/*updateMasterWmStAssmblNoPopBomQty*/
UPDATE WMSSTCK ST SET TOT_QTY = NVL(TOT_QTY,0)-(SELECT MAX(BOM_QTY) FROM WMSASSEMB WHERE AS_NO =#{st_as_no} AND BOM_ID = ST.STDCATLG_ID GROUP BY BOM_ID),
ALLOC_QTY = NVL(ALLOC_QTY,0)-(SELECT MAX(BOM_QTY) FROM WMSASSEMB WHERE AS_NO =#{st_as_no} AND BOM_ID = ST.STDCATLG_ID GROUP BY BOM_ID) ,
STC_SELLER_PRICE = decode((NVL(AVAIL_QTY,0)+(SELECT MAX(BOM_QTY) FROM WMSASSEMB WHERE AS_NO =#{st_as_no} AND BOM_ID = ST.STDCATLG_ID GROUP BY BOM_ID)),0,0,round((NVL(STC_SELLER_PRICE,0)*NVL(AVAIL_QTY,0)+(SELECT MAX(BOM_AMT) FROM WMSASSEMB WHERE AS_NO =#{st_as_no} AND BOM_ID = ST.STDCATLG_ID GROUP BY BOM_ID)) /(NVL(AVAIL_QTY,0)+(SELECT MAX(BOM_QTY) FROM WMSASSEMB WHERE AS_NO = #{st_as_no} AND BOM_ID = ST.STDCATLG_ID GROUP BY BOM_ID)),2)) , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), CHANGE_USER = #{st_user_id}
where (warehouse_code, stdcatlg_id) in ( select warehouse_code, bom_id from wmsassemb where as_no =#{st_as_no} group by warehouse_code, bom_id) and agent = 'KRKORE0001' AND PROCESS_TYPE = '1'

/*updateMasterWmStAssmblNoPopSubQty*/
UPDATE WMSSTCK ST SET TOT_QTY = NVL(TOT_QTY,0)+(SELECT SUM(SUB_QTY) FROM WMSASSEMB WHERE AS_NO =#{st_as_no} AND SUB_ID = ST.STDCATLG_ID AND STATUS <> 'D') , AVAIL_QTY = NVL(AVAIL_QTY,0)+(SELECT SUM(SUB_QTY) FROM WMSASSEMB WHERE AS_NO = #{st_as_no} AND SUB_ID = ST.STDCATLG_ID AND STATUS <> 'D'), PRE_GR_QTY = NVL(PRE_GR_QTY,0)-(SELECT SUM(SUB_QTY) FROM WMSASSEMB WHERE AS_NO =#{st_as_no}AND SUB_ID = ST.STDCATLG_ID AND STATUS <> 'D'), STC_SELLER_PRICE = decode((NVL(AVAIL_QTY,0)+(SELECT SUM(SUB_QTY) FROM WMSASSEMB WHERE AS_NO = #{st_as_no} AND SUB_ID = ST.STDCATLG_ID GROUP BY SUB_ID)),0,0,round((NVL(STC_SELLER_PRICE,0)*NVL(AVAIL_QTY,0)+(SELECT SUM(SUB_AMT) FROM WMSASSEMB WHERE AS_NO = #{st_as_no} AND SUB_ID = ST.STDCATLG_ID GROUP BY SUB_ID)) /(NVL(AVAIL_QTY,0)+(SELECT SUM(SUB_QTY) FROM WMSASSEMB WHERE AS_NO =#{st_as_no} AND SUB_ID = ST.STDCATLG_ID GROUP BY SUB_ID)),2)) ,
CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), CHANGE_USER = #{st_user_id}
WHERE (WAREHOUSE_CODE, STDCATLG_ID) IN ( SELECT WAREHOUSE_CODE, SUB_ID FROM WMSASSEMB ASS WHERE ASS.AS_NO =#{st_as_no} ) AND AGENT = 'KRKORE0001' AND PROCESS_TYPE = '1'

/*updateMasterWmStAssmblNoPopDate*/

		UPDATE  WMSASSEMB SET ASSEMB_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
					  ASSEMB_USER_ID = #{st_user_id},                                                  
					  ASSEMB_FLAG = 'Y'                                                                    
                         WHERE AS_NO =#{st_as_no}

/*updateMasterWmStAssmblNoPopAssemb*/

			UPDATE WMSASSEMB		
		SET STATUS = 'D'	
	WHERE AS_NO = #{st_as_no}  	
	  AND STATUS <> 'D'
